+// RF-004: total de una línea con descuento en porcentaje entero (0 a 100), aplicado antes del total
+// y redondeado al centavo (mitad hacia arriba). Todo en enteros: sin decimales binarios.
+export function totalLineaCentavos({ cantidad, precioUnitarioCentavos, descuentoPorcentaje = 0 }) {
+  if (!Number.isInteger(cantidad) || cantidad <= 0) throw new RangeError("Cantidad inválida");
+  if (!Number.isInteger(precioUnitarioCentavos) || precioUnitarioCentavos < 0)
+    throw new RangeError("Precio inválido: debe estar en centavos enteros");
+  if (!Number.isInteger(descuentoPorcentaje) || descuentoPorcentaje < 0 || descuentoPorcentaje > 100)
+    throw new RangeError("Descuento inválido: debe ser un porcentaje entero de 0 a 100");
+  const bruto = cantidad * precioUnitarioCentavos;
+  return Math.floor((bruto * (100 - descuentoPorcentaje) + 50) / 100);
+}
